"""Write r19/RESIDENT_RECIPE_AND_DELTA.json from the measured evidence (no value typed by hand except the
recipe text, which cites its file and line). ASCII only (ensure_ascii).

usage: python -I write_record.py <evidence dir> <out json>
"""
import json
import os
import re
import subprocess
import sys

