def load(name):
    with open(os.path.join(EV, name), encoding="utf-8") as fh:
        return json.load(fh)


def subject_of(source):
    out = subprocess.run(["git", "-C", SHARED, "log", "--format=%h%x09%s",
                          "%s..%s" % (PINS["old"], PINS["new"]), "--", source],
                         capture_output=True, text=True, encoding="utf-8", errors="replace").stdout
    lines = [ln for ln in out.splitlines() if ln.strip()]
    if not lines:
        return None, None
    commit, _, subj = lines[0].partition("\t")
    return commit, subj


CODES = ("ADVI_FIRMBKTS", "IRPT_ANLREQ", "IRPT_BCKEND", "IRPT_YCDGEN", "DSGN_IRPTV1", "NFRA_CTLPLN")


def owner_of(subject):
    for code in CODES:
        if re.search(r"\b%s\b" % code, subject or ""):
            return code
    if subject and "IB-pr-" in subject:
        return "IRPT_BCKEND"
    return "UNRESOLVED"


